"""Dump hyperglyphs generated by the REAL desktop engine to JSON.

The web app's Hyperglyph Generator is a port of the desktop dialog's generator
down to its random number source: the same Seed / Max Nodes / Branch Levels
must name the same design in both apps, or the Seed field means nothing outside
the app it was read in. That claim is not provable from inside JavaScript, so
this runs the desktop's own `random_recipe` / `generate_nodes` /
`assign_color_index` / `apply_idle_motion` — through `random.Random(seed)`,
CPython's Mersenne Twister — and dumps every node it produces.

`src/gv/hyperglyph.parity.test.ts` diffs the result field for field: integers
exactly, floats at 1e-9. A drift anywhere in the chain (the MT port, the order
of the rng calls in random_recipe, hsv conversion, half-to-even rounding, the
recipe's placement maths) shows up as a whole design diverging from its seed.

The cases below deliberately include:
  - branch level counts 1 (trunk only) through 6
  - a seed whose design comes out translucent (the alpha draws are CONDITIONAL,
    so they shift the whole downstream stream)
  - insertion parameters (start_id / parent_id / base_branch_level), which is
    the second call Insert into Scene makes
  - idle motion on and off

Run with the desktop repo's conda env python (see that repo's CLAUDE.md for how
to locate it; never `conda run`):

    <glyphviz-env-python> tools/dump_hyperglyphs.py src/gv/fixtures/hyperglyphs.json

Regenerate the vendored JSON only when the desktop generator changes. CI never
runs this — the JSON is committed.
"""

import json
import random
import sys
from pathlib import Path

# Import the desktop packages from the sibling repo without installing them.
DESKTOP_REPO = Path(__file__).resolve().parents[2] / "glyphviz"
sys.path.insert(0, str(DESKTOP_REPO))

from glyphviz_core.glyph_recipe import generate_nodes                    # noqa: E402
from hyperglyph_lab.hyperglyph_generator import (                        # noqa: E402
    apply_idle_motion, assign_color_index, random_recipe,
)

# (seed, branch_levels, max_nodes, idle_motion, start_id, parent_id, base_branch_level)
CASES = [
    (42, 5, 500, True, 1, 0, 0),          # the dialog's own defaults, Randomize off
    (42, 5, 500, False, 1, 0, 0),         # same design, idle motion withheld
    (0, 5, 500, True, 1, 0, 0),
    (1, 1, 500, True, 1, 0, 0),           # trunk only: no branching levels at all
    # Shallow trees have to keep their budget SMALL here: the desktop's
    # `pick_level_counts` raises ValueError from `randint` whenever
    # round(max_nodes ** (1/depth)) - 2 exceeds MAX_BRANCH (12), which is every
    # 2-level design over ~14 nodes and every 3-level one over ~196. That is a
    # real desktop bug (reported 2026-07-28); these two cases sit just under it
    # so the budget-trim path is still covered.
    (7, 2, 12, True, 1, 0, 0),
    (5, 3, 30, True, 1, 0, 0),
    (2024, 3, 196, True, 1, 0, 0),
    (12345, 4, 1000, True, 1, 0, 0),
    (999, 6, 3000, True, 1, 0, 0),        # deepest, and the largest budget
    (2147483646, 5, 500, True, 1, 0, 0),  # top of the Seed field's range
    (777, 4, 300, True, 501, 42, 3),      # inserted under a level-2 node
    (31337, 5, 120, True, 88, 7, 1),
]

# Fields generate_nodes/assign_color_index/apply_idle_motion actually write.
# Everything else on a Node is a dataclass default and is checked on the web
# side by the shared blankNode factory, not here.
FIELDS = [
    "id", "type", "parent_id", "branch_level",
    "translate_x", "translate_y", "translate_z",
    "rotate_x", "rotate_y", "rotate_z",
    "scale_x", "scale_y", "scale_z",
    "color_r", "color_g", "color_b", "color_a",
    "geometry", "hide", "topo", "ratio", "rotation_mode", "color_index",
    # Stamped by generate_nodes since desktop 88091e1: an angular level under a
    # Pin parent is fitted to TOPO_SCALE_ANTZ, which is what stops it smearing
    # 360 world units up the pin's axis. No rng draw moved, so every other
    # column here is unchanged from the previous fixture.
    "topo_scale",
    "rotate_rate_x", "rotate_rate_y", "rotate_rate_z",
]


def main() -> int:
    if len(sys.argv) != 2:
        print(__doc__)
        return 2
    out_path = Path(sys.argv[1])

    cases = []
    for seed, levels, max_nodes, idle, start_id, parent_id, base_branch in CASES:
        recipe, meta = random_recipe(levels, max_nodes, random.Random(seed),
                                     name="Hyperglyph")
        nodes = generate_nodes(recipe, start_id=start_id, parent_id=parent_id,
                               base_branch_level=base_branch)
        assign_color_index(nodes)
        if idle:
            # A FRESH Random(seed), exactly as the dialog does it, so the spin
            # is reproducible from the design's own seed alone.
            apply_idle_motion(nodes, random.Random(seed))
        cases.append({
            "seed": seed,
            "branch_levels": levels,
            "max_nodes": max_nodes,
            "idle_motion": idle,
            "start_id": start_id,
            "parent_id": parent_id,
            "base_branch_level": base_branch,
            "geometry_family": meta["geometry_family"],
            "palette_scheme": meta["palette_scheme"],
            "translucent": bool(meta["translucent"]),
            "level_counts": list(meta["level_counts"]),
            "nodes": [
                {f: getattr(n, f) for f in FIELDS}
                for n in nodes
            ],
        })

    out_path.parent.mkdir(parents=True, exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump({"cases": cases}, f, indent=1)
    total = sum(len(c["nodes"]) for c in cases)
    print(f"Wrote {len(cases)} case(s), {total} node(s) -> {out_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
